const m = $json.meeting_data || {};
const a = $json.ai_analysis || {};
const list = (arr) => (arr && arr.length) ? '<ul>' + arr.map(x => `<li>${x}</li>`).join('') + '</ul>' : '<p>Sin informacion registrada.</p>';
const html = `
<h1>ACTA DE REUNIÓN CON REPRESENTANTE</h1>
<h2>1. Datos generales</h2>
<p>Estudiante: ${m.student_name || ''} | Curso: ${m.course || ''}</p>
<p>Representante: ${m.representative_name || ''}</p>
<p>Docente: ${m.teacher_name || ''}</p>
<p>Fecha: ${m.date || ''} | Hora: ${m.start_time || ''}</p>
<h2>2. Motivo de la reunión</h2><p>${a.meeting_reason || ''}</p>
<h2>3. Antecedentes relevantes</h2>${list(a.situations_discussed)}
<h2>4. Temas tratados</h2>${list(a.topics)}
<h2>5. Intervenciones relevantes</h2>${list(a.student_interventions)}
<h2>6. Situaciones analizadas</h2>${list(a.situations_discussed)}
<h2>7. Acuerdos</h2>${list(a.agreements)}
<h2>8. Compromisos</h2>${list(a.commitments)}
<h2>9. Responsables</h2>${list(a.responsible_people)}
<h2>10. Evidencias mencionadas</h2>${list(a.evidence_mentions)}
<h2>11. Fecha o acciones de seguimiento</h2><p>${a.follow_up_date || 'No definida'}</p>${list(a.follow_up_actions)}
<h2>12. Observaciones</h2><p>${a.requires_teacher_review ? 'Requiere revisión docente antes de aprobar.' : ''}</p>
<h2>13. Firmas</h2><p>Pendiente de firma digital.</p>
`;
return [{ json: { meeting_id: m.meeting_id, draft_html: html, status: 'draft', ai_analysis: a } }];
